    lines = sys.stdin.read().strip().splitlines()
    if len(lines) != 2:
        raise ValueError("Invalid input")
    d1 = parse_date(lines[0])
    d2 = parse_date(lines[1])
    delta = abs(d2 - d1)
    print(delta.days)

if __name__ == "__main__":
    main()
