def normalize(dx, dy):
    """Normalize the direction vector to represent the same line."""
    if dx == 0 and dy == 0:
        return (0, 0)
    # Find greatest common divisor
    g = math.gcd(abs(dx), abs(dy))
    dx //= g
    dy //= g
    # Ensure consistent direction
    if dx == 0:
        # Vertical line, make dy positive
        if dy < 0:
            dy = -dy
    else:
        # Non-vertical, make dx positive
        if dx < 0:
            dx = -dx
            dy = -dy
    return (dx, dy)

n, x0, y0 = map(int, input().split())
lines = set()

for _ in range(n):
    x, y = map(int, input().split())
    dx = x - x0
    dy = y - y0

    # Normalize the direction vector
    lines.add(normalize(dx, dy))

print(len(lines))
"}

