def solve():
    T = int(input())

    for _ in range(T):
        n, m = map(int, input().split())

        edges = []
        for i in range(1, m + 1):
            u, v = map(int, input().split())
            edges.append((u, v))

        # Create adjacency list
        adj = {i: [] for i in range(1, 3 * n + 1)}
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Try to find a matching of size n
        matching = []
        selected_vertices = set()

        for edge_idx, (u, v) in enumerate(edges, 1):
            if u not in selected_vertices and v not in selected_vertices:
                matching.append(edge_idx)
                selected_vertices.add(u)
                selected_vertices.add(v)

        if len(matching) == n:
            print("Matching")
            print(" ".join(map(str, matching)))
            continue

        # Try to find an independent set of size n
        independent_set = []

        for v in range(1, 3 * n + 1):
            # Check if v forms an independent set with current selection
            if all(v not in adj[u] for u in independent_set):
                independent_set.append(v)

        if len(independent_set) == n:
            print("IndSet")
            print(" ".join(map(str, independent_set)))
            continue

        print("Impossible")

solve()
