    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    counts = [0] * 31
    for num in a:
        d = num.bit_length() - 1
        if d < 31:
            counts[d] += 1
    max_bit = 30
    out_lines = []
    for _ in range(q):
        b = int(next(it))
        total = 0
        for i in range(max_bit, -1, -1):
            coin = 1 << i
            if coin > b:
                continue
            cnt = counts[i]
            use = min(cnt, b // coin)
            total += use
            b -= use * coin
            if b == 0:
                break
        if b == 0:
            out_lines.append(str(total))
        else:
            out_lines.append('-1')
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()
"}

