import sys
from bisect import bisect_left

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    s = next(it)
    char_positions = {}
    for i, ch in enumerate(s, start=1):
        if ch not in char_positions:
            char_positions[ch] = []
        char_positions[ch].append(i)

    out_lines = []
    for _ in range(n):
        c = next(it)
        len_c = len(c)
        total = 0
        for i in range(len_c):
            ch = c[i]
            if ch not in char_positions:
                total += len_c
                continue
            pos_list = char_positions[ch]
            target = i + 1
            idx = bisect_left(pos_list, target)
            best = float('inf')
            if idx > 0:
                best = min(best, abs(target - pos_list[idx-1]))
            if idx < len(pos_list):
                best = min(best, abs(target - pos_list[idx]))
            total += best
        out_lines.append(str(total))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

