n, x0, y0 = map(int, input().split())
slopes = set()

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def reduce_fraction(a, b):
    g = gcd(abs(a), abs(b))
    return (a // g, b // g)

for _ in range(n):
    x, y = map(int, input().split())

dx = x - x0
    dy = y - y0

    # If dx is 0, it's a vertical line - represent with (1, 0)
    if dx == 0:
        slopes.add((1, 0))
    else:
        # Normalize the slope representation
        g = gcd(abs(dx), abs(dy))
        dy_reduced, dx_reduced = reduce_fraction(dy, dx)
        slopes.add((dy_reduced, dx_reduced))

print(len(slopes))
"}

