def compute_growth(x, k, b, s):
    if k == 1:
        return x + b * s

    # Compute k^s and k^s - 1 using exponentiation by squaring
    power = 1
    for _ in range(s):
        power *= k
    return power * x + b * (power - 1) // (k - 1)

