def solve():
    n = int(input())
    s = input().strip()

    k = s.count('H')

    # Brute force approach: check if current configuration is valid
    # and try all possible windows

    # For a configuration to be valid:
    # - All hamsters should be adjacent to each other (except maybe when there's only 1 hamster)
    # - All tigers should be adjacent to each other

    def is_valid(s):
        # Check if all hamsters are adjacent to each other (except when there's only 1 hamster)
        # This is tricky... let me think about what constitutes 'adjacent'

        # If there's only 1 hamster, it's always valid
        if k == 1:
            return True

        # Find the positions of hamsters
        hamster_positions = [i for i, c in enumerate(s) if c == 'H']

        # Check if each hamster is adjacent to at least one other hamster
        for i in hamster_positions:
            if i == hamster_positions[0]:
                # Check if it's adjacent to hamster_positions[1] (wrap around)
                if i + 1 < n:
                    if s[i+1] == 'H':
                        continue
                if s[0] == 'H':
                    if hamster_positions[1] == 0:
                        continue
                return False
            elif i == hamster_positions[-1]:
                # Check if it's adjacent to hamster_positions[-2]
                if i - 1 >= 0:
                    if s[i-1] == 'H':
                        continue
                if s[n-1] == 'H':
                    if hamster_positions[-2] == n-1:
                        continue
                return False
            else:
                # Check if it's adjacent to either neighbor
                if s[i-1] == 'H' or s[i+1] == 'H':
                    continue
                return False

        # Check if all tigers are adjacent to each other
        if n - k == 1:
            return True

        tiger_positions = [i for i, c in enumerate(s) if c == 'T']
        for i in tiger_positions:
            if i == tiger_positions[0]:
                if i + 1 < n:
                    if s[i+1] == 'T':
                        continue
                if s[0] == 'T':
                    if tiger_positions[1] == 0:
                        continue
                return False
            elif i == tiger_positions[-1]:
                if i - 1 >= 0:
                    if s[i-1] == 'T':
                        continue
                if s[n-1] == 'T':
                    if tiger_positions[-2] == n-1:
                        continue
                return False
            else:
                if s[i-1] == 'T' or s[i+1] == 'T':
                    continue
                return False

        return True

    # Try all possible configurations by rotating the string
    # For a circle, rotating gives us all possible configurations
    for i in range(n):
        rotated = s[i:] + s[:i]
        if is_valid(rotated):
            print(0)
            return

    # If not found, try brute force to find minimal swaps
    # Brute force is O(n^3) which should be fine for n=1000

    # Count number of H's and T's
    h_count = k
    t_count = n - k

    # For each possible window of size h_count (containing all H's)
    min_swaps = h_count
    for start in range(n):
        # Count number of T's in this window
        t_in_window = 0
        for i in range(start, start + h_count):
            if s[i % n] == 'T':
                t_in_window += 1
        min_swaps = min(min_swaps, t_in_window)

    print(min_swaps)

solve()
