def solve():
    n = int(input())
    fragments = [input().strip() for _ in range(n)]

    # Remove fragments that are substrings of other fragments
    to_keep = []
    for i, frag in enumerate(fragments):
        is_substring = False
        for j, other_frag in enumerate(fragments):
            if i != j and frag in other_frag:
                is_substring = True
                break
        if not is_substring:
            to_keep.append(frag)
    fragments = to_keep

    # If only one fragment, return it
    if len(fragments) == 1:
        print(fragments[0])
        return

    # Try all permutations of the fragments
    from itertools import permutations
    shortest = None

    for perm in permutations(fragments):
        # Build the string by concatenating and collapsing duplicates
        result = ""
        for frag in perm:
            result += frag

        # Collapse consecutive duplicate letters
        collapsed = []
        prev = None
        for c in result:
            if c != prev:
                collapsed.append(c)
                prev = c
        result = ''.join(collapsed)

        # Check if all fragments are substrings
        valid = True
        for frag in fragments:
            if frag not in result:
                valid = False
                break

        if valid:
            if shortest is None or len(result) < len(shortest):
                shortest = result
            elif len(result) == len(shortest):
                # Tie-breaker: choose lexicographically smaller
                if result < shortest:
                    shortest = result

    print(shortest)

solve()
