def solve():
    MOD = 998244353
    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    # dp[x] = number of ways to achieve XOR value x
    dp = {0: 1}
    for val in a:
        new_dp = dp.copy()
        for x in dp:
            new_val = x ^ val
            new_dp[new_val] = (new_dp.get(new_val, 0) + dp[x]) % MOD
        dp = new_dp

    # Count number of 1-bits for each XOR result
    result = [0] * (m + 1)
    for x, count in dp.items():
        bits = bin(x).count('1')
        if bits <= m:
            result[bits] = (result[bits] + count) % MOD

    print(' '.join(map(str, result)))

