def solve():
    n, k = map(int, input().split())
    adj = [[] for _ in range(n)]
    for _ in range(n-1):
        u, v = map(int, input().split())
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    # dp[u][d] = number of ways to paint the subtree rooted at u such that u is at distance d from nearest black
    dp = [[0]*(k+1) for _ in range(n)]

    def dfs(u, parent):
        # u is black
        dp[u][0] = 1

        for v in adj[u]:
            if v == parent:
                continue
            dfs(v, u)

        # u is not black but within distance d of nearest black
        for d in range(1, k+1):
            for v in adj[u]:
                if v == parent:
                    continue
                # v can be at any distance 0..d-1 from black
                # this means u can be at distance d from black
                for d2 in range(d):
                    dp[u][d] = (dp[u][d] + dp[v][d2]) % MOD

    dfs(0, -1)

    print(dp[0][0])

solve()
