import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    s = []
    c = []
    for _ in range(n):
        s.append(int(next(it)))
        c.append(int(next(it)))

    ans = float('inf')

    for j in range(1, n-1):  # j must have at least one left and one right
        # Compute min left cost where i < j and s[i] < s[j]
        min_left = float('inf')
        for i in range(j):
