import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx]); idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx]); idx += 1

        # Parse voters
        voters = []
        for i in range(n):
            m_i = int(data[idx]); p_i = int(data[idx + 1])
            idx += 2
            voters.append((m_i, p_i))

        supporters = 0
        total_cost = 0

        # Create a list of candidates for each m_i value
        # We'll keep track of which voters are still available
        available = [True] * n

        while True:
            # Find all voters with m_i = supporters
            can_get_for_free = []
            for i in range(n):
                if available[i] and voters[i][0] == supporters:
                    can_get_for_free.append(i)

            if can_get_for_free:
                # Get all of them for free
                for i in can_get_for_free:
                    available[i] = False
            else:
                break

            # If we still have voters, we need to buy one
            if any(available):
                # Find the voter with the smallest p_i who is still available
                best_i = -1
                best_p = float('inf')
                for i in range(n):
                    if available[i] and voters[i][1] < best_p:
                        best_i = i
                        best_p = voters[i][1]

                total_cost += best_p
                supporters += 1

        results.append(str(total_cost))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
