import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    ptr = 0
    q = int(data[ptr])
    ptr += 1

    for _ in range(q):
        # Skip empty lines (empty lines may have only whitespace, we'll just skip them)
        while ptr < len(data) and data[ptr] == "":
            ptr += 1

        if ptr >= len(data):
            break

        n, k = int(data[ptr]), int(data[ptr+1])
        ptr += 2

        a = []
        for _ in range(k):
            a.append(int(data[ptr]))
            ptr += 1

        t = []
        for _ in range(k):
            t.append(int(data[ptr]))
            ptr += 1

        # Sort air conditioners by position
        pos = [(a[i], t[i]) for i in range(k)]
        pos.sort()

        # Compute min_left[i] = min(t_j - a_j for air conditioners at positions <= i)
        min_left = [float('inf')] * (n + 2)

        # Compute min_right[i] = min(t_j + a_j for air conditioners at positions >= i)
        min_right = [float('inf')] * (n + 2)

        # Left to right pass
        for i in range(1, n + 1):
            for (aj, tj) in pos:
                if aj <= i:
                    min_left[i] = min(min_left[i], tj - aj)

        # Right to left pass
        for i in range(n, 0, -1):
            for (aj, tj) in pos:
                if aj >= i:
                    min_right[i] = min(min_right[i], tj + aj)

        # Compute answers
        ans = []
        for i in range(1, n + 1):
            ans.append(str(min(min_left[i] + i, min_right[i] - i)))

        print(' '.join(ans) + ' ')

if __name__ == "__main__":
    solve()
