    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        tree[u].append(v)
        tree[v].append(u)

    # dp[u][d]: number of ways to color the subtree rooted at u such that u is at distance d from the nearest black vertex
    # We need to ensure that d <= k
    # Initialize with zeros
    dp = [{} for _ in range(n + 1)]

    # Post-order traversal
    def dfs(u, parent):
        for v in tree[u]:
            if v == parent:
                continue
            dfs(v, u)

        # dp[u][0]: u is painted black
        dp[u][0] = 1
        for v in tree[u]:
            if v == parent:
                continue
            # All children can be in any state
            for d, ways in dp[v].items():
                dp[u][0] = (dp[u][0] * ways) % MOD

        # dp[u][1]: u is not painted black, but at least one neighbor is painted black (covers u)
        if len(tree[u]) >= 1:
            ways = 0
            for v in tree[u]:
                if v == parent:
                    continue
                # Choose v to be painted black (d = 0)
                # v can be in any state, but we need to consider its children
                for w in tree[v]:
                    if w != u:
                        for dw, w_ways in dp[w].items():
                            if dw == 0:
                                # v is painted black
                                # v's parent (which could be u) is not painted black
                                pass
                            else:
                                pass
                # Actually, this is getting too complex
                # Let's use a different approach: precompute total ways for each child
                total = sum(dp[v].values()) % MOD
                # Choose v to be painted black
                chosen_ways = 1
                for w in tree[v]:
                    if w != u:
                        chosen_ways = (chosen_ways * (sum(dp[w].values()) % MOD + 1)) % MOD
                ways = (ways + chosen_ways) % MOD
            dp[u][1] = ways

        # dp[u][2]: u is not painted black, and none of its neighbors is painted black
        dp[u][2] = 1
        for v in tree[u]:
            if v == parent:
                continue
            dp[u][2] = (dp[u][2] * sum(dp[v][d] for d in dp[v].keys())) % MOD

    dfs(1, -1)

    # Answer is the number of ways where the root is covered (distance <= k)
    # This includes: root is painted black (d = 0), root is not painted black but covered (d = 1)
    answer = 0
    for d in dp[1].keys():
        if d <= k:
            answer = (answer + dp[1][d]) % MOD
    print(answer)

