n, m = map(int, input().split())

# Build adjacency list
adj = [[] for _ in range(n + 1)]
for i in range(m):
    u, v = map(int, input().split())
    adj[u].append((v, i))
    adj[v].append((u, i))

# Find bridges using Tarjan's algorithm
visited = [False] * (n + 1)
low = [0] * (n + 1)
discovery_time = [0] * (n + 1)
time_counter = [1]
bridges = set()

def find_bridges(start):
    stack = [(start, -1, False)]
    parent = [-1] * (n + 1)

    while stack:
        v, p, is_back_edge = stack.pop()
        if visited[v]:
            if not is_back_edge:
                stack.append((v, p, True))

                for neighbor, idx in adj[v]:
                    if neighbor == p:
                        continue
                    if visited[neighbor]:
                        low[v] = min(low[v], discovery_time[neighbor])
                        if low[neighbor] > discovery_time[v]:
                            bridges.add(idx)
                    else:
                        parent[neighbor] = v
                        low[v] = min(low[v], low[neighbor])
                        stack.append((neighbor, v, False))
            continue

        visited[v] = True
        discovery_time[v] = time_counter[0]
        low[v] = time_counter[0]
        time_counter[0] += 1

        for neighbor, idx in adj[v]:
            if neighbor == p:
                continue
            if visited[neighbor]:
                low[v] = min(low[v], discovery_time[neighbor])
            else:
                stack.append((neighbor, v, False))
                stack.append((v, p, True))

find_bridges(1)

if len(bridges) > 0:
    print(0)
else:
    # Orient edges to make strongly connected
    # Use DFS to find a spanning tree and orient edges
    parent = [-1] * (n + 1)
    result = [[] for _ in range(m)]

    def dfs(v, p):
        for neighbor, idx in adj[v]:
            if neighbor == p:
                continue
            if parent[neighbor] == -1:
                parent[neighbor] = v
                dfs(neighbor, v)

            # Orient tree edge away from root
            if parent[neighbor] == v:
                result[idx] = (v, neighbor)
            else:
                # Orient back edge towards ancestor
                result[idx] = (neighbor, v)

    dfs(1, -1)

    for p, q in result:
        print(p, q)
