    year = 1989
    while True:
        year_str = str(year)
        found = False

        # Check all suffix lengths from shortest to longest
        for length in range(1, len(year_str) + 1):
            # Check each possible suffix of this length
            for i in range(len(year_str) - length + 1):
                suffix_candidate = year_str[i:i+length]

                # This suffix hasn't been used yet
                if suffix_candidate not in used:
                    # Check if any shorter suffix has been used
                    is_shortest = True
                    for shorter_length in range(1, length):
                        # Check all suffixes of this length
                        for j in range(len(year_str) - shorter_length + 1):
                            if year_str[j:j+shorter_length] in used:
                                is_shortest = False
                                break
                        if not is_shortest:
