import sys
from collections import defaultdict, deque

def read_input():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return []
    n = int(data[0].strip())
    fragments = data[1:n+1]
    return fragments

def build_graph(fragments):
    graph = defaultdict(lambda: defaultdict(int))
    indegree = defaultdict(int)
    outdegree = defaultdict(int)

    for fragment in fragments:
        if len(fragment) == 1:
            continue
        for i in range(len(fragment) - 1):
            u = fragment[i]
            v = fragment[i + 1]
            graph[u][v] += 1
            outdegree[u] += 1
            indegree[v] += 1
    return graph, indegree, outdegree

def find_eulerian_path(graph, indegree, outdegree, nodes):
    # Find start node
    start = None
    for node in nodes:
        diff = outdegree[node] - indegree[node]
        if diff == 1:
            start = node
            break
    else:
        # If no start node found, try all nodes
        for node in nodes:
            if outdegree[node] > 0:
                start = node
                break

    # Hierholzer's algorithm
    stack = [start]
    path = []

    while stack:
        current = stack[-1]
        if graph[current]:
            next_node = next(iter(graph[current]))
            stack.append(next_node)
            graph[current][next_node] -= 1
            if graph[current][next_node] == 0:
                del graph[current][next_node]
        else:
            path.append(stack.pop())

    # Convert to string
    return ''.join(path)

def solve():
    fragments = read_input()

    # Build graph
    graph, indegree, outdegree = build_graph(fragments)

    # Collect all unique nodes
    nodes = set()
    for fragment in fragments:
        for c in fragment:
            nodes.add(c)

    if len(nodes) == 1:
        # Only one unique character, print it
        print(fragments[0])
        return

    # Find Eulerian path
    path = find_eulerian_path(graph, indegree, outdegree, nodes)

    # Ensure all fragments are present
    for fragment in fragments:
        if fragment not in path:
            # If not found, try a different path
            # Start from a different node
            for start_node in nodes:
                if start_node == path[0]:
                    continue
                path = find_eulerian_path(graph, indegree, outdegree, nodes)
                if fragment in path:
                    break

    print(path)

if __name__ == '__main__':
    solve()
