import sys

def cyclic_shift_right(arr, l, r):

    if l == r:
        return

    # Save the value at the start of the segment
    value = arr[l-1]

    # Shift all elements from position l to r-1 to the right
    for i in range(l-1, r-1):
        arr[i] = arr[i+1]

    # Place the saved value at the end of the segment
    arr[r-1] = value

def reverse_segment(arr, l, r):

    # Reverse the segment
    for i in range(l-1, (l + r) // 2):
        arr[i], arr[(l + r) - 1 - i] = arr[(l + r) - 1 - i], arr[i]


def main():
    data = sys.stdin.read().split()
    if not data:
        return

