for i in range(n - 1):
    # f(i, i+1) = 1 + (sum of a[i+1..i+1])^2 = 1 + a[i+1]^2
    f = 1 + a[i + 1] ** 2
    if f < min_f:
        min_f = f

# Also check non-consecutive pairs for completeness
for i in range(1, n):
    for j in range(i + 1, n + 1):
        # g(i,j) = sum of a[k] for k from i+1 to j (or j+1 to i if i > j)
        # Using prefix sums, sum from i+1 to j = prefix[j] - prefix[i]
        if i < j:
            sum_g = prefix[j] - prefix[i]
        else:
            sum_g = prefix[i] - prefix[j]

        f = (i - j) ** 2 + sum_g ** 2
        if f < min_f:
            min_f = f

print(min_f)
