    n = int(next(it))
    m = int(next(it))
    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    # Precompute left_actor[i][j]: nearest actor to the left (<= j-1) in row i
    left_actor = [[-1]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                left_actor[i][j] = -1
            else:
                if j > 0:
                    left_actor[i][j] = left_actor[i][j-1]
                else:
                    left_actor[i][j] = -1

    # Right_actor[i][j]: nearest actor to the right (> j) in row i
    right_actor = [[-1]*m for _ in range(n)]
    for i in range(n):
        for j in range(m-1, -1, -1):
            if grid[i][j] == 1:
                right_actor[i][j] = -1
            else:
                if j < m-1:
                    right_actor[i][j] = right_actor[i][j+1]
                else:
                    right_actor[i][j] = -1

    # Up_actor[i][j]: nearest actor above (<= i-1) in column j
    up_actor = [[-1]*m for _ in range(n)]
    for j in range(m):
        for i in range(n):
