    down_actor = [[-1]*m for _ in range(n)]
    for j in range(m):
        for i in range(n-1, -1, -1):
            if grid[i][j] == 1:
                down_actor[i][j] = -1
            else:
                if i < n-1:
                    down_actor[i][j] = down_actor[i+1][j]
                else:
                    down_actor[i][j] = -1

