import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    s = [int(next(it)) for _ in range(n)]
    c = [int(next(it)) for _ in range(n)]
    INF = 10**18
    left_min = [INF] * n
    for j in range(n):
        for i in range(j):
            if s[i] < s[j]:
                if c[i] < left_min[j]:
                    left_min[j] = c[i]
    right_min = [INF] * n
    for j in range(n):
        for k in range(j+1, n):
            if s[k] > s[j]:
                if c[k] < right_min[j]:
                    right_min[j] = c[k]
    ans = INF
    for j in range(n):
        if left_min[j] < INF and right_min[j] < INF:
            current = left_min[j] + c[j] + right_min[j]
            if current < ans:
                ans = current
    print(-1 if ans == INF else ans)

if __name__ == "__main__":
    main()
"}

