import math

x, y = map(int, input().split())

# Calculate the distance from the origin
distance = math.sqrt(x ** 2 + y ** 2)

# Determine quadrant
quadrant = 0
if x > 0 and y > 0:
    quadrant = 1
elif x < 0 and y > 0:
    quadrant = 2
elif x < 0 and y < 0:
    quadrant = 3
else:
    quadrant = 4

# Points on the border (integer distance) are black
if distance.is_integer():
    print("black")
else:
    # Determine which annular region we're in
    n = int(distance)

    # Checkerboard pattern based on n and quadrant
    if (n + quadrant) % 2 == 0:
        print("white")
    else:
        print("black")
"}

