def get_divisors(n):
    """Return a list of all divisors of n (excluding n itself)."""
    divisors = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            if i < n:
                divisors.add(i)
            if n // i < n and n // i != i:
                divisors.add(n // i)
    return sorted(divisors)

def solve():
    import sys
    input = sys.stdin.read
    data = input().strip().split()

    idx = 0
    t = int(data[idx])
    idx += 1
    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        s = list(map(int, data[idx:idx+n]))
        idx += n

        # dp[i]: longest sequence ending at index i (1-indexed)
        dp = [1] * (n + 1)  # dp[0] unused

        for i in range(1, n + 1):
            # Find all divisors d of i where d < i
            divisors = get_divisors(i)

            for d in divisors:
                if s[d - 1] < s[i - 1]:
                    dp[i] = max(dp[i], dp[d] + 1)

        results.append(str(max(dp)))

    sys.stdout.write("\n".join(results))

