    for _ in range(T):
        n = int(input())
        a = list(map(int, input().split()))

        if n < 2:
            print(-1)
            continue

        found = False
        result = -1

        # Try all subarrays starting from each position
        for i in range(n):
            freq = {}
            max_freq = 0
            max_element = None

            for j in range(i, n):
                element = a[j]
                freq[element] = freq.get(element, 0) + 1

                if freq[element] > max_freq:
                    max_freq = freq[element]
                    max_element = element

                # Check if current window [i, j] is dominated
                dominated = True
                for key, count in freq.items():
                    if key != max_element and count == max_freq:
                        dominated = False
                        break

                if dominated:
                    result = j - i + 1
                    found = True
                    break

        print(result if found else -1)

