# Compute prefix sums (1-indexed)
S = [0] * (n + 1)
for i in range(1, n + 1):
    S[i] = S[i - 1] + a[i - 1]  # a[0] is first element

# Find the minimum distance where prefix sums are equal
min_distance = float('inf')
for i in range(n):
    for j in range(i + 1, n):
        if S[i + 1] == S[j + 1]:
            dist = (i + 1) - j  # distance between indices (1-indexed)
            if dist < 0:
                dist = -dist
            if dist < min_distance:
                min_distance = dist

# The answer is (distance)^2
print(min_distance * min_distance)
