def main():
    n = int(input())
    s = input().strip()

    max_h_segment = 0
    max_t_segment = 0

    # Count contiguous segments of H and T in a linear way
    for i in range(n):
        if s[i] == 'H':
            h_count = 1
            for j in range(i + 1, n):
                if s[j] == 'H':
                    h_count += 1
                else:
                    break
            max_h_segment = max(max_h_segment, h_count)

        if s[i] == 'T':
            t_count = 1
            for j in range(i + 1, n):
                if s[j] == 'T':
                    t_count += 1
                else:
                    break
            max_t_segment = max(max_t_segment, t_count)

    # Now check if the farthest apart H's are adjacent
    h_positions = [i + 1 for i, ch in enumerate(s) if ch == 'H']
    t_positions = [i + 1 for i, ch in enumerate(s) if ch == 'T']

    # Find farthest H and farthest T
    farthest_h = max(h_positions)
    farthest_t = max(t_positions)

    # Distance in circle: min(|x - y|, n - |x - y|)
    def circle_distance(x, y):
        return min(abs(x - y), n - abs(x - y))

    # Check if the farthest H's are adjacent
    h_adjacent = False
    for i in range(len(h_positions) - 1):
        if circle_distance(h_positions[i], h_positions[i + 1]) == 1:
            h_adjacent = True
            break

    # Check if the farthest T's are adjacent
    t_adjacent = False
    for i in range(len(t_positions) - 1):
        if circle_distance(t_positions[i], t_positions[i + 1]) == 1:
            t_adjacent = True
            break

    # Calculate swaps
    if h_adjacent:
        swaps = n - max(h_positions)
    elif t_adjacent:
        swaps = n - max(t_positions)
    else:
        swaps = n - max(max_h_segment, max_t_segment)

    print(swaps)

if __name__ == "__main__":
    main()
