def normalize(amulet):
    """Return the canonical form of an amulet by rotating to the smallest form"""
    a, b, c, d = amulet
    rotations = [
        (a, b, c, d),  # 0 degrees
        (b, d, a, c),  # 90 degrees clockwise
        (c, d, b, a),  # 180 degrees
        (d, c, a, b)   # 270 degrees clockwise
    ]

    # Find the lexicographically smallest rotation
    return min(rotations)

def main():
    n = int(input())

    groups = {}

    for i in range(n):
        # Read the two lines of the amulet
        if i > 0:
            while True:
                separator = input().strip()
                if separator == "**":
                    break

        line1 = input().strip()
        line2 = input().strip()

        # Parse the amulet: first line = top row, second line = bottom row
        a, b = int(line1[0]), int(line1[1])
        c, d = int(line2[0]), int(line2[1])
        amulet = (a, b, c, d)

        canonical = normalize(amulet)

        # Group amulets by their canonical form
        if canonical not in groups:
            groups[canonical] = 0
        groups[canonical] += 1

    # Output the number of piles (number of unique canonical forms)
    print(len(groups))

if __name__ == "__main__":
    main()
