def is_similar(amulet1, amulet2):
    """Check if two amulets are similar"""
    a1, b1, c1, d1 = amulet1
    a2, b2, c2, d2 = amulet2

    # Check if one can be rotated to match the other
    # 0 degrees: (a1, b1, c1, d1) == (a2, b2, c2, d2)
    # 90 degrees: (c1, a1, d1, b1) == (a2, b2, c2, d2)
    # 180 degrees: (c1, d1, b1, a1) == (a2, b2, c2, d2)
    # 270 degrees: (b1, d1, a1, c1) == (a2, b2, c2, d2)

    return (
        amulet1 == amulet2 or
        (c1, a1, d1, b1) == amulet2 or
        (c1, d1, b1, a1) == amulet2 or
        (b1, d1, a1, c1) == amulet2
    )

def main():
    n = int(input())

    # Read all amulets
    amulets = []

    for i in range(n):
        if i > 0:
            while True:
                separator = input().strip()
                if separator == "**":
                    break

        line1 = input().strip()
        line2 = input().strip()

        # Parse the amulet: first line = top row, second line = bottom row
        a, b = int(line1[0]), int(line1[1])
        c, d = int(line2[0]), int(line2[1])
        amulets.append((a, b, c, d))

    # Group similar amulets
    groups = {}

    for i, amulet in enumerate(amulets):
        found = False

        for j, existing in enumerate(amulets):
            if i != j and is_similar(amulet, existing):
                # Add to existing group
                key = tuple(sorted([i, j]))
                if key not in groups:
                    groups[key] = 0
                groups[key] += 1
                found = True
                break

        if not found:
            # Start a new group
            groups[tuple([i])] = 1

    print(len(groups))

if __name__ == "__main__":
    main()
