def is_substring(s, i, j, end):
    """Check if s[j:end] is a substring of s[0:i]"""
    if j == 0:
        return False  # Can't be a substring of empty string
    # Check if s[j:end] is in s[0:i]
    return s[j:end] in s[:i]

def solve():
    n, a, b = map(int, input().split())
    s = input().strip()

    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0  # Base case: 0 characters, 0 cost

    for i in range(1, n + 1):
        for j in range(i):
            # Try to split: first part ends at j, second part is s[j:i]
            length = i - j
            if length == 1:
                cost = a
            else:
                # Check if s[j:i] is a substring of s[0:j]
                # Actually, we need it to be a substring of the previous parts, which is s[0:i-1]
                # But if length > 1, we need to check if it appears earlier
                if j > 0 and s[j:i] in s[:j]:
                    cost = b
                else:
                    cost = INF  # Can't use b for multi-character strings that don't appear earlier
            dp[i] = min(dp[i], dp[j] + cost)

    print(dp[n])

solve()
