{"code": "
import sys
import bisect

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    s = next(it)
    s_positions = {}

    for idx, ch in enumerate(s):
        if ch not in s_positions:
            s_positions[ch] = []
        s_positions[ch].append(idx + 1)  # 1-indexed positions

    out_lines = []
    for _ in range(n):
        c = next(it)
        m = len(c)
        F = 0

        for i, ch in enumerate(c):
            i_idx = i + 1  # 1-indexed
            if ch in s_positions:
                # Find closest position in s_positions[ch] using binary search
                positions = s_positions[ch]
                pos = bisect.bisect_left(positions, i_idx)

                if pos == 0:
                    closest = positions[0]
                elif pos == len(positions):
                    closest = positions[-1]
                else:
                    closest = min(positions[pos - 1], positions[pos])

                F += abs(i_idx - closest)
            else:
                F += m

        out_lines.append(str(F))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

