def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    idx = 0
    T = int(data[idx])
    idx += 1

    out = []

    for _ in range(T):
        n = int(data[idx])
        m = int(data[idx + 1])
        idx += 2

        edges = []
        for i in range(m):
            u = int(data[idx]) - 1  # 0-indexed
            v = int(data[idx + 1]) - 1
            idx += 2
            edges.append((u, v))

        if m > 2 * n:
            # Find matching of size n
            match = []
            used = [False] * (3 * n)

            for i, (u, v) in enumerate(edges):
                if not used[u] and not used[v]:
                    match.append(i + 1)  # 1-indexed edge index
                    used[u] = True
                    used[v] = True

            if len(match) >= n:
                out.append("Matching")
                out.append(' '.join(map(str, match[:n])))
            else:
                out.append("Impossible")
        else:
            # Find independent set of size n
            indep = []
            used = [False] * (3 * n)

            for i, (u, v) in enumerate(edges):
                if not used[u]:
                    indep.append(u + 1)  # 1-indexed vertex index
                    used[u] = True
                elif not used[v]:
                    indep.append(v + 1)
                    used[v] = True

            if len(indep) >= n:
                out.append("IndSet")
                out.append(' '.join(map(str, indep[:n])))
            else:
                out.append("Impossible")

    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    solve()
