    matches_two = float('inf')
    for a in [min_x, max_x]:
        for b in [min_x, max_x]:
            if a != b:
                # Solve a * k + b * (n-k) = n * avg
                # => k = (n * avg - b * n) / (a - b)
                numerator = n * avg - b * n
                denominator = a - b
                if abs(denominator) < 1e-9:
                    continue  # parallel lines
                k = numerator / denominator
                if 0 <= k <= n:
                    y = [a] * k + [b] * (n - k)
                    match_count = sum(1 for i in range(n) if y[i] == x[i])
