def dfs(start, visited, prev, adj, path, max_path):
    visited[start] = True
    path.append(start)

    for neighbor in adj[start]:
        if neighbor == prev:
            continue
        if not visited[neighbor]:
            dfs(neighbor, visited, start, adj, path, max_path)
        else:
            # Found a cycle
            cycle_len = len(path) + 1
            cycle_path = path + [neighbor]
            if cycle_len >= 3 and cycle_len % 3 != 0:
                max_path[0] = cycle_len
