import sys
from collections import defaultdict, deque

def solve():
    n = int(sys.stdin.readline())
    if n == 1:
        print("Impossible")
        return

    a = list(map(int, sys.stdin.readline().split()))

    # Build tree
    tree = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        tree[u].append(v)
        tree[v].append(u)

    # DFS to calculate in-time, out-time, and subtree sums
    in_time = [0] * (n + 1)
    out_time = [0] * (n + 1)
    subtree_sum = [0] * (n + 1)
    time = 1

    def dfs(u, parent):
        nonlocal time
        in_time[u] = time
        time += 1
        subtree_sum[u] = a[u - 1]

        for v in tree[u]:
            if v != parent:
                dfs(v, u)
                subtree_sum[u] += subtree_sum[v]
                out_time[u] = max(out_time[u], out_time[v])

        out_time[u] = time - 1

    dfs(1, -1)

    # Find maximum sum of two disjoint subtrees
    max_sum = -1

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if in_time[i] < in_time[j] and out_time[i] > out_time[j]:
                continue  # i is ancestor of j
            if in_time[j] < in_time[i] and out_time[j] > out_time[i]:
                continue  # j is ancestor of i

            total = subtree_sum[i] + subtree_sum[j]
            if total > max_sum:
                max_sum = total

    if max_sum == -1:
        print("Impossible")
    else:
        print(max_sum)

if __name__ == "__main__":
    solve()
