def solve():
    n = int(input())
    s = input().strip()
    m = int(input())
    words = []
    for _ in range(m):
        parts = input().split()
        words.append((parts[0], int(parts[1])))
    x = int(input())

    # dp[i][j] = max score for first i positions, using each position at most j times
    # We'll use a 1D array for space efficiency
    dp = [0] * (x + 1)

    for i in range(n):
        # Consider all words that end at position i
        # Since words can be placed starting at position i-l+1 to i
        # For each word length l, we can check if s[i-l+1:i+1] matches
        for l in range(1, i + 1):
            if s[i - l + 1:i + 1] in {w[0] for w in words}:
                for word, value in words:
                    if word == s[i - l + 1:i + 1]:
                        # We can place this word at position i-l+1, ending at i
                        # We need to update dp[j] for all j where we can place this word
                        for j in range(x, -1, -1):
                            if j >= l:
                                # We can place this word if we have enough capacity
                                dp[j] = max(dp[j], dp[j - l] + value)

    print(max(dp))

solve()
