MOD = 998244353

def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    # Build linear basis
    basis = [0] * m
    for num in a:
        x = num
        for i in range(m):
            if (x >> i) & 1:
                if basis[i] == 0:
                    basis[i] = x
                    break
                else:
                    x ^= basis[i]
                    if x == 0:
                        break

    # Sort basis by position
    basis = [x for x in basis if x != 0]
    basis.sort(key=lambda x: x.bit_length())

    # Dynamic programming
    dp = [0] * (m + 1)
    dp[0] = 1

    for x in basis:
        i = x.bit_length() - 1

        # Update dp: we can include this basis vector
        for j in range(m, -1, -1):
            if dp[j] > 0:
                dp[j ^ (1 << i)] = (dp[j ^ (1 << i)] + dp[j]) % MOD

    print(' '.join(map(str, dp)))

solve()
