import sys

def find_year(abbrev):
    # Extract the suffix
    if not abbrev.startswith("IAO'") or abbrev[-1] != ":":
        return None
    suffix = abbrev[4:-1]

    # If no suffix, return None
    if not suffix:
        return None

    # Try to find the year by simulating the process
    year = 1989
    used = set()

    while True:
        # Find the shortest suffix that hasn't been used
        found = False
        for k in range(1, len(str(year)) + 1):
            last_k_digits = str(year)[-k:] if year >= 10**k else str(year).zfill(k)
            if last_k_digits not in used:
                used.add(last_k_digits)
                found = True
                break

        if found:
            if last_k_digits == suffix:
                return year

        year += 1

# Test function
def test():
    n = int(input())
    for _ in range(n):
        abbrev = input().strip()
        print(find_year(abbrev))

# Run with standard input/output
if __name__ == "__main__":
    test()
"}

