counts = {}
for coin in coins:
    power = coin.bit_length() - 1
    counts[power] = counts.get(power, 0) + 1

for _ in range(q):
    b = int(input())

    # Find all powers that we need (bits set in b)
    needed_powers = []
    for i in range(b.bit_length() + 1):
        if b & (1 << i):
            needed_powers.append(i)

    # Check if we have coins for all needed powers
    has_all = True
    for power in needed_powers:
        if counts.get(power, 0) == 0:
            has_all = False
            break

    if not has_all:
        print(-1)
    else:
        # We have all needed powers, answer is number of set bits
        # But wait, we might have multiple coins of some powers - do we need all?
        # Actually, we only need one of each power
        print(len(needed_powers))
