def solve():
    q = int(input())
    for _ in range(q):
        n = int(input())
        elements = list(map(int, input().split()))

        # Count powers of two
        counts = {}
        for num in elements:
            power = num.bit_length() - 1  # This works because powers of two have only one bit set
            counts[power] = counts.get(power, 0) + 1

        # Work from smallest to largest power
        for power in sorted(counts.keys()):
            # We can create floor(counts[power]/2) of the next power
            pairs = counts[power] // 2
            counts[power + 1] = counts.get(power + 1, 0) + pairs
            # If we've created 2048, we win
            if power + 1 == 11:
                print("YES")
                break
        else:
            # If we never reached 2048
            print("NO")

solve()
