import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n = int(data[0])
    k = int(data[1])
    s = data[2]

    # Preprocess user address: store positions of each character
    pos = {}
    for i, ch in enumerate(s):
        pos[ch] = pos.get(ch, []) + [i + 1]  # 1-indexed positions

    # Process each potential address
    out = []
    idx = 3
    for _ in range(n):
        c = data[idx]
        idx += 1

        total = 0
        for i, ch in enumerate(c, 1):  # i is 1-indexed
            if ch not in pos:
                total += len(c)
            else:
                # Find closest position j in s
                positions = pos[ch]
                # Binary search for closest
                left, right = 0, len(positions)
                while left < right:
                    mid = (left + right) // 2
                    if positions[mid] < i:
                        left = mid + 1
                    else:
                        right = mid

                # left is the insertion point (first position >= i)
                candidates = []
                if left > 0:
                    candidates.append(positions[left - 1])
                if left < len(positions):
                    candidates.append(positions[left])

                if candidates:
                    j = min(candidates, key=lambda x: abs(x - i))
                    total += abs(i - j)
                else:
                    total += len(c)

        out.append(str(total))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
"}

