import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    c = list(map(int, data[1:1+m]))
    x, y = int(data[1+m]), int(data[1+m+1])
    prefix = [0] * (m + 1)
    for i in range(1, m + 1):
        prefix[i] = prefix[i - 1] + c[i - 1]
    total = prefix[m]
    for k in range(1, m + 1):
        beg = prefix[k - 1]
        intm = total - beg
        if x <= beg <= y and x <= intm <= y:
            print(k)
            return
    print(0)

if __name__ == "__main__":
    solve()
